DO $$
BEGIN
  IF (SELECT count(*) FROM public.job_postings WHERE deleted_at IS NULL AND department = 'Office of the City General Services Officer'
        AND education_requirement IS NOT NULL AND posted_by = 'HR Admin') <> 24
     OR (SELECT count(*) FROM public.job_postings WHERE deleted_at IS NULL AND department = 'Office of the City General Services Officer' AND status = 'Open') <> 5
     OR (SELECT count(*) FROM public.departments d JOIN public.departments p ON p.id = d.parent_department_id WHERE p.code = 'OCGSO') <> 5
  THEN RAISE EXCEPTION 'GSO fix-up counts do not match; rolled back'; END IF;
END $$;

COMMIT;
